CREATE TABLE
    book (
        id BIGSERIAL PRIMARY KEY,
        title VARCHAR(45),
        author VARCHAR(45),
        description TEXT,
        copies INT,
        copies_available INT,
        category VARCHAR(11),
        img BYTEA
    );

ALTER TABLE book
ALTER COLUMN id
SET DEFAULT nextval ('book_id_seq');

