-- Queries for table review
CREATE TABLE
    review (
        id BIGSERIAL PRIMARY KEY,
        user_email VARCHAR(45),
        date TIMESTAMPTZ,
        rating DECIMAL(3, 2),
        book_id BIGINT,
        review_description TEXT
    );

ALTER TABLE review
ALTER COLUMN id
SET DEFAULT nextval ('review_id_seq');

