-- Queries for table checkout
CREATE TABLE
    checkout (
        id BIGSERIAL PRIMARY KEY,
        user_email VARCHAR(45),
        checkout_date VARCHAR(45),
        return_date VARCHAR(45),
        book_id BIGINT
    );

ALTER TABLE checkout
ALTER COLUMN id
SET DEFAULT nextval ('checkout_id_seq');

-- Queries for table messages
CREATE TABLE
    messages (
        id BIGSERIAL PRIMARY KEY,
        user_email VARCHAR(45),
        title VARCHAR(45),
        question TEXT,
        admin_email VARCHAR(45),
        response TEXT,
        closed BOOLEAN DEFAULT FALSE
    );

ALTER TABLE messages
ALTER COLUMN id
SET DEFAULT nextval ('messages_id_seq');

-- Queries for table history
CREATE TABLE
    history (
        id BIGSERIAL PRIMARY KEY,
        user_email VARCHAR(45),
        checkout_date VARCHAR(45),
        returned_date VARCHAR(45),
        title VARCHAR(45),
        author VARCHAR(45),
        description TEXT,
        img BYTEA
    );

ALTER TABLE history
ALTER COLUMN id
SET DEFAULT nextval ('history_id_seq');


-- Queries for table payment
CREATE TABLE
    payment (
        id BIGSERIAL PRIMARY KEY,
        user_email VARCHAR(45),
        amount NUMERIC(10, 2)
    );
ALTER TABLE payment
ALTER COLUMN id
SET DEFAULT nextval ('payment_id_seq');